import React, { PropsWithChildren, SVGProps } from 'react';
import styled from 'styled-components';
export interface ForeignObjectWrapperProps
  extends SVGProps<SVGForeignObjectElement> {
  containerWidth?: string;
}

export const StyledContainer = /* @__PURE__ */ styled('div')<{
  width?: string;
}>(({ width }) => ({
  position: 'fixed',
  width,
}));

/**
 * Component to wrap a child element into a foreign object forcing the parent to be position fixed.
 * The main goal of this wrapper is to prevent positioning issues on Safari.
 */
export const ForeignObjectWrapper = ({
  children,
  ...props
}: PropsWithChildren<ForeignObjectWrapperProps>) => {
  const { containerWidth, ...foreignObjectProps } = props;

  return (
    <foreignObject {...foreignObjectProps}>
      <StyledContainer width={containerWidth}>{children}</StyledContainer>
    </foreignObject>
  );
};
